CREATE TEMP TABLE eligible_tournament_winners ON COMMIT DROP AS SELECT DISTINCT ON(r.id_user) r.id_user,r.id,r.time FROM public.record r JOIN public."user" u ON u.id=r.id_user JOIN public.track_tournament t ON t.id=$1 WHERE r.id_level=t.id_level AND ((r.date_created>=t.start_at AND r.date_created<t.end_at) OR EXISTS(SELECT 1 FROM public.track_tournament_result accepted WHERE accepted.id_tournament=t.id AND accepted.id_record=r.id)) AND NOT u.banned AND r.record_eligible ORDER BY r.id_user,r.time,r.date_created,r.id
